"""Single, decimal-exact price policy for generation and both submission gates.

Facts and an exact existing exception supply authority; a checksum alone does not.
This module neither obtains prices nor writes platform or ERP state.
"""
from decimal import Decimal, InvalidOperation, ROUND_CEILING
import hashlib
import json

VERSION = 'campaign-price-decision-v1'


def money(value, *, positive=True):
    if isinstance(value, bool):
        raise ValueError('invalid_price')
    try:
        number = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid_price') from None
    if not number.is_finite() or number < 0 or (positive and number == 0):
        raise ValueError('invalid_price')
    if number != number.quantize(Decimal('.01')):
        raise ValueError('invalid_price_precision')
    return number


def digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
                                    separators=(',', ':'), allow_nan=False).encode()).hexdigest()


def signup_rule(row, daily, basis, *, lowering_authorized=False, failed_exact=False):
    price, daily = money(row['activity_price']), money(daily)
    if row.get('custom') is not True:
        if price != daily:
            raise ValueError('ordinary_signup_must_equal_erp_daily')
        return
    if basis:
        original = money(basis['original'])
        floor = (original * Decimal('.20')).quantize(Decimal('.01'), rounding=ROUND_CEILING)
        # A caller cannot rebase the fixed floor on a later reduced price.
        if Decimal(str(basis['floor'])) != original * Decimal('.20'):
            raise ValueError('fixed_floor_not_first_original_twenty_percent')
        if not basis.get('source'):
            raise ValueError('fixed_basis_source_missing')
        if price < floor:
            raise ValueError('below_first_original_twenty_percent')
    if price == daily:
        return
    if price > daily:
        raise ValueError('custom_increase_not_authorized')
    if not lowering_authorized or not failed_exact:
        raise ValueError('exact_failed_custom_lowering_authority_required')
    if basis is None or basis.get('uncertain'):
        raise ValueError('exact_custom_lowering_basis_unknown')


def final_rule(final, target):
    if abs(money(final) - money(target)) > Decimal('2'):
        raise ValueError('ordinary_final_outside_fixed_target')


def decide(row, identity, *, exception=None, exception_validator=None):
    """Decide one source-verified checklist row; retain exact context in result."""
    price = money(row['activity_price'])
    target = money(row['target_price'])
    rule = 'ordinary_daily_and_fixed_target'
    if row.get('custom') is True:
        if row.get('price_basis') == 'unchanged_daily_no_fixed_basis':
            if not row.get('unchanged_daily_evidence') or price != money(row['daily_price']):
                raise ValueError('unchanged_custom_source_required')
            rule = 'unchanged_custom_source_verified_separately'
        else:
            original = money(row['original_price'])
            floor = (original * Decimal('.20')).quantize(Decimal('.01'), rounding=ROUND_CEILING)
            if price < floor:
                raise ValueError('below_first_original_twenty_percent')
            rule = 'first_original_twenty_percent'
    else:
        daily = money(row['daily_price'])
        if price != daily:
            if not exception or exception_validator is None:
                raise ValueError('ordinary_signup_must_equal_erp_daily')
            exception_validator(row, identity, exception)
            rule = 'exact_authorized_exception_and_fixed_target'
        final_rule(row['final_price'], target)
    facts = {k: row[k] for k in sorted(row) if k not in ('product_name', 'stock', 'route', 'rotation_reason')}
    body = dict(version=VERSION, identity=identity, facts=facts, rule=rule,
                exception=exception if rule.startswith('exact_') else None)
    return dict(body, sha256=digest(body))


def approved_exception(row, identity, exception):
    """Reuse the existing exact two-SKU authorization; never generalize it."""
    from campaign_ginkgo_price_exception import validate_row
    if not identity.get('official_rate') or identity.get('target') not in ('big', 'mid'):
        raise ValueError('exact_price_decision_context_required')
    original = dict(code=row['erp_code'], daily=row['daily_price'],
                    big_target=row['target_price'], custom=False)
    candidate = dict(item=str(row['item']), sku=str(row['sku']), erp_code=row['erp_code'],
                     activity_price=row['activity_price'], target=row['target_price'],
                     big_target=row['target_price'], custom=False, price_exception=exception)
    context = dict(campaign='/'.join(str(identity[k]) for k in
                   ('campaign_id', 'phase_id', 'sign_record_id')),
                   start=identity['start'], end=identity['end'],
                   target=identity['target'], official_rate=identity['official_rate'])
    validate_row(candidate, original, context)


def checklist_decisions(checklist, *, exception=None):
    context = checklist['price_decision_context']
    identity = checklist['identity']
    if any(context.get(k) != v for k, v in identity.items()):
        raise ValueError('price_decision_identity_mismatch')
    if not context.get('price_version'):
        raise ValueError('price_decision_source_version_required')
    rows = checklist['rows']
    pairs = [(str(r['item']), str(r['sku'])) for r in rows]
    if len(pairs) != len(set(pairs)):
        raise ValueError('price_decision_duplicate_sku')
    decisions = [decide(r, context, exception=exception,
                        exception_validator=approved_exception) for r in rows]
    body = dict(version=VERSION, context=context, decisions=decisions,
                source_evidence=checklist['source_evidence'])
    return dict(body, sha256=digest(body))


def verify_checklist_decisions(checklist, *, exception=None):
    expected = checklist_decisions(checklist, exception=exception)
    if checklist.get('price_decisions') != expected:
        raise ValueError('price_decision_binding_changed')
    return expected

