def tables(db):
    db.executescript('''
      CREATE TABLE IF NOT EXISTS campaign_ui_takeovers(
        job_id TEXT PRIMARY KEY, request_id TEXT NOT NULL, packet TEXT NOT NULL,
        state TEXT NOT NULL, previous_result TEXT NOT NULL, sequence INTEGER NOT NULL DEFAULT 0);
      CREATE UNIQUE INDEX IF NOT EXISTS campaign_ui_single_owner ON campaign_ui_takeovers((1))
        WHERE state IN ('active','write_unknown');
      CREATE TABLE IF NOT EXISTS campaign_ui_events(
        job_id TEXT NOT NULL, sequence INTEGER NOT NULL, operation TEXT NOT NULL,
        evidence TEXT NOT NULL, PRIMARY KEY(job_id,sequence));
      CREATE TABLE IF NOT EXISTS campaign_ui_commands(
        job_id TEXT NOT NULL, sequence INTEGER NOT NULL, operation TEXT NOT NULL,
        state TEXT NOT NULL, result TEXT, PRIMARY KEY(job_id,sequence));
    ''')


def active(db):
    found=db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='campaign_ui_takeovers'").fetchone()
    return bool(found and db.execute("SELECT 1 FROM campaign_ui_takeovers WHERE state IN ('active','write_unknown')").fetchone())


def session_owned(session):
