def event(db,jid,operation,evidence):
    db.execute('BEGIN IMMEDIATE')
    try:
        row=db.execute('SELECT sequence FROM campaign_ui_takeovers WHERE job_id=?',(jid,)).fetchone()
        if row is None or (row[0]>=MAX_ACTIONS and operation!='release'):raise SurfaceError('takeover_action_limit_reached')
        seq=row[0]+1
        db.execute('INSERT INTO campaign_ui_events VALUES(?,?,?,?)',(jid,seq,operation,json.dumps(evidence,ensure_ascii=False)))
        db.execute('UPDATE campaign_ui_takeovers SET sequence=? WHERE job_id=?',(seq,jid))
        db.execute('COMMIT');return seq
    except BaseException:
        db.execute('ROLLBACK');raise


def original_action(rid,jid,*,root=None):
    root=Path(root or ROOT)
    if not all(re.fullmatch('[0-9a-f]{64}',str(v)) for v in (rid,jid)):
        raise SurfaceError('takeover_exact_task_and_job_required')
    with sqlite3.connect((root/'jobs.sqlite3').resolve(strict=True).as_uri()+'?mode=ro',uri=True) as db:
        row=db.execute('SELECT state FROM continuous_jobs WHERE id=?',(rid,)).fetchone()
        if not row or row[0] not in ('blocked','unknown','finished'):
            raise SurfaceError('takeover_requires_paused_original_controller')
        if db.execute("SELECT 1 FROM continuous_jobs WHERE state='running'").fetchone():
            raise SurfaceError('takeover_controller_still_running')
    folder=root/'runs'/rid
    request=json.loads((root/'requests'/(rid+'.json')).read_text(encoding='utf-8'))
    if fingerprint(request)!=rid:raise SurfaceError('takeover_original_request_changed')
    refs=[]
    for path in folder.rglob('*-job.json'):
        ref=json.loads(path.read_text(encoding='utf-8'))
        if ref.get('job_id')==jid and ref.get('step') in SUPPORTED:refs.append((path,ref))
    if len(refs)!=1:raise SurfaceError('takeover_original_job_reference_not_unique')
    path,ref=refs[0]
    with sqlite3.connect((folder/'controller.sqlite3').resolve(strict=True).as_uri()+'?mode=ro',uri=True) as db:
