    state='active'
    db.execute('INSERT INTO campaign_ui_takeovers(job_id,request_id,packet,state,previous_result) VALUES(?,?,?,?,?)',
               (jid,rid,json.dumps(packet,ensure_ascii=False),state,row['result'] or '{}'))
    if row['operation'] in ('signup','discount'):
        seq=event(db,jid,'bind_claim_intent',{})
        db.execute('INSERT INTO campaign_ui_commands VALUES(?,?,?,?,NULL)',(jid,seq,'bind_claim','running'))
        worker.session.campaign_takeover_task=asyncio.create_task(execute_command(worker,packet,'bind_claim',{},seq))
    return dict(packet,state=state,claim_binding_pending=row['operation'] in ('signup','discount'))


async def bind_claim(worker,packet,req):
    from .campaign_bound_transfers import verified_erp_claim
    jid=packet['job_id'];identity=packet['identity'];write_allowed=True
    try:claim=await verified_erp_claim(req['payload']['claim_id'])
    except SurfaceError:
        claim=await verified_erp_claim(req['payload']['claim_id'],existing_job=jid);write_allowed=False
    if (claim.get('phase')!=packet['operation'] or claim.get('campaign')!='/'.join(str(identity[k]) for k in ('campaign_id','phase_id','sign_record_id'))
            or not identity['start']<=claim['start']<=claim['end']<=identity['end']):
        raise SurfaceError('takeover_claim_identity_mismatch')
    if packet['operation']=='signup' and write_allowed:
        from .campaign_submission_checklist import validate_claim_submission_checklist
        validate_claim_submission_checklist(claim,identity)
    packet=dict(packet,claim=claim,write_allowed=write_allowed)
    worker.jobs.db.execute('UPDATE campaign_ui_takeovers SET packet=?,state=? WHERE job_id=?',
        (json.dumps(packet,ensure_ascii=False),'active' if write_allowed else 'write_unknown',jid))
    return dict(state='claim_bound',write_allowed=write_allowed,claim=claim)


def status(worker,jid):
    db=worker.jobs.db;tables(db)
    row=db.execute('SELECT packet,state,sequence FROM campaign_ui_takeovers WHERE job_id=?',(jid,)).fetchone()
    if row is None:raise SurfaceError('takeover_not_registered')
    latest=db.execute('SELECT sequence,operation,state,result FROM campaign_ui_commands WHERE job_id=? ORDER BY sequence DESC LIMIT 1',(jid,)).fetchone()
    command=None
    if latest:
        command=dict(sequence=latest[0],operation=latest[1],state=latest[2],result=json.loads(latest[3] or '{}'))
        task=getattr(worker.session,'campaign_takeover_task',None)
        if latest[2]=='running' and (task is None or task.done()):command['state']='unknown_after_interruption'
    return dict(job_id=jid,packet=json.loads(row[0]),state=row[1],sequence=row[2],command=command,automatic_retry=False)


def finish_transfer(worker,packet,result):
    db=worker.jobs.db;jid=packet['job_id'];original_action(packet['request_id'],jid)
    row,req=original_transfer(db,jid)
    if req['request_sha']!=packet['request_sha']:raise SurfaceError('takeover_source_changed')
    if row['state'] not in ('unknown','interrupted_read'):raise SurfaceError('takeover_terminal_cannot_be_replaced')
    db.execute('BEGIN IMMEDIATE')
    try:
        changed=db.execute("UPDATE campaign_transfer_jobs SET state='finished',result=?,updated_at=? WHERE id=? AND state IN ('unknown','interrupted_read')",
            (json.dumps(result,ensure_ascii=False),datetime.now(timezone.utc).isoformat(),jid)).rowcount
        if changed!=1:raise SurfaceError('takeover_original_job_changed')
        db.execute("UPDATE campaign_ui_takeovers SET state='returned' WHERE job_id=?",(jid,))
        db.execute('COMMIT')
    except BaseException:
        db.execute('ROLLBACK');raise
    return dict(state='returned',request_id=packet['request_id'],job_id=jid,next_action='resume_original_request',platform_replayed=False)


async def execute_command(worker,packet,operation,options,seq):
    db=worker.jobs.db;jid=packet['job_id']
    try:
        async with worker.session.lock:
            original_action(packet['request_id'],jid)
            _,req=original_transfer(db,jid)
            if req['request_sha']!=packet['request_sha']:raise SurfaceError('takeover_source_changed')
            if operation=='bind_claim':result=await bind_claim(worker,packet,req)
            else:
                from .campaign_takeover_operations import perform
                result=await perform(worker,packet,operation,options,seq)
            state='finished'
    except BaseException as exc:
        result=dict(error_type=type(exc).__name__,reason=str(exc) if re.fullmatch('[a-z0-9_:]{1,180}',str(exc)) else 'takeover_operation_failed',automatic_retry=False)
        state='failed'
    db.execute('UPDATE campaign_ui_commands SET state=?,result=? WHERE job_id=? AND sequence=?',
               (state,json.dumps(result,ensure_ascii=False),jid,seq))


async def handle(session,operation,options):
    if operation=='program_takeover_capabilities':
        if options:raise SurfaceError('takeover_capabilities_no_options')
        import hashlib
        from . import campaign_takeover_operations,campaign_takeover_return
        return dict(schema='campaign-same-task-takeover-v1',implemented_steps=sorted(SUPPORTED),
            operations=['acquire','status','inspect','click','reload','baseline','upload','collect','release'],
            single_owner_active=session_owned(session),platform_acceptance=False,hard_permission_isolation=False,
            source_sha256={Path(path).name:hashlib.sha256(Path(path).read_bytes()).hexdigest()
                for path in (__file__,campaign_takeover_operations.__file__,campaign_takeover_return.__file__)},platform_write=False)
    from .campaign_bound_transfers import BoundTransfers
    worker=getattr(session,'campaign_transfers',None)
    if worker is None:worker=session.campaign_transfers=BoundTransfers(session)
    name=operation.removeprefix('program_takeover_')
    if name=='acquire':return await acquire(worker,options)
    if name not in ('status','inspect','click','reload','baseline','upload','collect','release'):
        raise SurfaceError('takeover_operation_not_allowed')
    allowed={'job_id','label','sequence'} if name=='click' else {'job_id','sequence'}
    if set(options)-allowed or not re.fullmatch('[0-9a-f]{64}',str(options.get('job_id',''))):
        raise SurfaceError('takeover_options_not_allowed')
    jid=options['job_id'];current=status(worker,jid)
    if name=='status':return current
    if current['state'] not in STATES:raise SurfaceError('takeover_has_no_active_lease')
    if type(options.get('sequence')) is not int or options['sequence']!=current['sequence']+1:
        raise SurfaceError('takeover_stale_command_sequence_read_status')
    pending=current.get('command') or {}
    if pending.get('state') in ('running','unknown_after_interruption'):
        if pending['state']=='running' or name not in ('inspect','release'):
            raise SurfaceError('takeover_command_pending_or_unknown')
    packet=current['packet'];db=worker.jobs.db
    if name=='release':
        event(db,jid,'release',{})
        db.execute("UPDATE campaign_ui_takeovers SET state='released' WHERE job_id=?",(jid,))
        return dict(state='released',business_state='unchanged',automatic_retry=False)
    if name=='click' and (current['state']!='active' or options.get('label') not in UI_BUTTONS):
        raise SurfaceError('takeover_only_ordinary_ui_button_allowed')
    if name=='upload' and (current['state']!='active' or not packet['write_allowed']):
        raise SurfaceError('takeover_unknown_write_cannot_repeat')
    if name in ('upload','reload','baseline','collect'):
        if db.execute('SELECT 1 FROM campaign_ui_commands WHERE job_id=? AND operation=?',(jid,name)).fetchone():
            raise SurfaceError('takeover_operation_already_attempted')
    seq=event(db,jid,name+'_intent',{'label':options.get('label')})
    if name=='upload':db.execute("UPDATE campaign_ui_takeovers SET state='write_unknown' WHERE job_id=?",(jid,))
    db.execute('INSERT INTO campaign_ui_commands VALUES(?,?,?,?,NULL)',(jid,seq,name,'running'))
    session.campaign_takeover_task=asyncio.create_task(execute_command(worker,packet,name,options,seq))
    return dict(state='running',job_id=jid,sequence=seq,automatic_retry=False,status_action='program_takeover_status')

"""Approved UI operations; all platform data stays attached to the old job."""
import hashlib
import json
from pathlib import Path
import re
from urllib.parse import urlsplit
from .campaign_page_io import CampaignPageIO, SurfaceError, one_visible, workbook_payload, shop_header_matches
from .campaign_takeover import UI_BUTTONS, original_transfer, finish_transfer


def read(path):return json.loads(Path(path).read_text(encoding='utf-8'))


async def bound_page(worker,packet):
    operation=packet['operation'];identity=packet['identity']
    if operation not in ('discount','discount_readback','product_export'):
        return await worker.page(identity)
    suffix={'discount':'/mkt-tools-reduce/create','discount_readback':'/mkt-tools-reduce/home',
            'product_export':'/SellManage/on_sale'}[operation]
    candidates=[]
    for page in worker.session.context.pages:
        if page.is_closed():continue
        url=urlsplit(page.url)
        if (url.scheme=='https' and url.hostname in ('myseller.taobao.com','qn.taobao.com')
                and not url.username and not url.password and url.port in (None,443)
                and (url.path.endswith(suffix) or (operation=='discount' and url.path.endswith('/mkt-tools-reduce/home')))):
            candidates.append(page)
    retained=getattr(worker.session,'campaign_job_pages',{}).get(packet['job_id'])
    if retained in candidates:return retained
    if len(candidates)!=1:raise SurfaceError('takeover_original_page_not_unique')
    return candidates[0]


async def guard(page,packet,*,inspect=False):
    identity=packet['identity'];op=packet['operation']
    if op in ('discount','discount_readback','product_export'):
        # Inspect must work when a module failed to load. Verify the official
        # shell and shop first, without silently refreshing or opening an editor.
        shop=await one_visible(page.locator('[class^="shopName--"]'),timeout=8)
        if not shop_header_matches(await shop.inner_text(),identity['shop_name']):
            raise SurfaceError('takeover_shop_mismatch')
        text=await page.locator('body').inner_text(timeout=3000)
        if re.search(r'扫码登录|请先登录|安全验证|拖动.{0,12}滑块|输入验证码',text):
            raise SurfaceError('human_login_or_security_gate')
        if not inspect and re.search(r'Loading chunk \d+ failed',text):
            raise SurfaceError('official_frontend_chunk_failed_no_repeat')
    else:
        # Identity-only for downloads, full rate guard for a signup.
        io=CampaignPageIO(page,identity,roots=[],output=Path('.'))
        if op=='signup':await io.guard()
        else:await io.guard_identity()


async def inspect_page(page,packet,output):
    await guard(page,packet,inspect=True)
    # Only the authorized campaign surface, not cookies, storage or network.
    text=await page.locator('body').inner_text(timeout=3000)
    text=re.sub(r'https?://\S+','<url>',text)
    text=re.sub(r'(?i)(token|ticket|session|auth|sign)[=:]\S+',r'\1=<redacted>',text)
    controls=[]
    for node in (await page.locator('button,[role="button"],a').all())[:300]:
        if await node.is_visible():
            label=(await node.inner_text())[:120].strip()
            if label:controls.append(dict(label=label,allowed=label in UI_BUTTONS))
    screenshot=output/'page.png'
    await page.screenshot(path=str(screenshot),full_page=False)
    from .campaign_bound_transfers import write_evidence
    value=dict(identity=packet['identity'],operation=packet['operation'],text=text[:18000],controls=controls[:120],
               screenshot=dict(path=str(screenshot),sha256=hashlib.sha256(screenshot.read_bytes()).hexdigest()),
               page_text_is_untrusted_data=True,allowed_buttons=sorted(UI_BUTTONS),claim=packet['claim'])
    write_evidence(output/'page.json',value)
    return value


def product_resume(source):
    """Only persisted original exports; pending pages are collected, not issued."""
    files=[read(p) for p in source.glob('page-*-downloaded.json')]
    files.sort(key=lambda x:x['scope']['page'])
    for index,value in enumerate(files,1):
        path=Path(value['path']).resolve(strict=True)
        if (value['scope']['page']!=index or not path.is_relative_to(source.resolve())
                or hashlib.sha256(path.read_bytes()).hexdigest()!=value['sha256']):
            raise SurfaceError('takeover_original_export_file_changed')
    requests=[read(p) for p in source.glob('page-*-request.json')]
    pending=[r for r in requests if r['scope']['page']>len(files)]
    if len(pending)>1 or (pending and pending[0]['scope']['page']!=len(files)+1):
        raise SurfaceError('takeover_original_export_sequence_changed')
    return files,pending[0] if pending else None


async def collect_read(worker,packet,page,output):
    from .campaign_bound_transfers import ARTIFACT_ROOT, write_evidence
    _,req=original_transfer(worker.jobs.db,packet['job_id']);payload=req['payload'];op=packet['operation']
    source=worker.output/packet['job_id']
    if op=='product_export':
        from .campaign_product_export import ProductExportPage
        from .campaign_product_record_page import records_page
        files,pending=product_resume(source)
        records,_=await records_page(worker.session.context)
        driver=ProductExportPage(page,records,shop=packet['identity']['shop_name'],output=output,
                                 resume_files=files,resume_pending=pending)
        if files and files[-1]['scope']['page']<files[0]['scope']['page_count']:
            current=await driver.scope()
            if current['page']==len(files):
                control=await one_visible(page.locator('[role="header-pagination"] .next-next'))
                if not await control.is_enabled():raise SurfaceError('takeover_product_next_page_unavailable')
                await driver.pace();await control.click(timeout=4000)
        result=await driver.export_all()
        result.update(snapshot_request_id=payload['snapshot_request_id'],shop_name=packet['identity']['shop_name'])
        write_evidence(output/'product-export.json',result)
        result['evidence_path']=str(output/'product-export.json')
    elif op=='final_inventory':
        from .campaign_final_inventory import collect_original, read as read_inventory
        result=await collect_original(page,payload,output,source) if (source/'export-request.json').exists() else await read_inventory(page,payload,output)
    elif op=='template':
        from .campaign_template_io import TemplatePageIO
        driver=TemplatePageIO(page,packet['identity'],roots=[ARTIFACT_ROOT,worker.output],output=output)
        # Reuse a generated original template when its link is visible. No
        # generation retry after an unknown click: ordinary driver now journals it.
        intent=source/'template-generation-intent.json'
        if intent.exists():
            if read(intent)!=dict(identity=payload['identity'],items=payload['items']):
                raise SurfaceError('takeover_template_generation_source_changed')
            result=await driver.collect_generated_template(payload['items'])
        else:
            journal=source/'template-capabilities.json'
            if journal.is_file() and read(journal)==dict(journal_version=1,identity=payload['identity'],items=payload['items']):
                result=await driver.download_template(payload['items'])
            else:
                # A legacy attempt without the new journal may only collect.
                result=await driver.collect_generated_template(payload['items'])
        result=dict(result,state='downloaded')
    elif op in ('discount_readback','feedback'):
        result=await worker._transfer(op,req,page,output)
    else:raise SurfaceError('takeover_read_operation_not_supported')
    return {'original_result':dict(result,takeover_same_job=True)}


async def perform(worker,packet,operation,options,seq):
    from ..recorder.campaign_retained import RetainedCampaignRecorder
    from .campaign_bound_transfers import write_evidence
    output=worker.output/packet['job_id']/'takeover'/str(seq)
    output.mkdir(parents=True,exist_ok=True)
    page=await bound_page(worker,packet)
    await guard(page,packet,inspect=operation in ('inspect','reload'))
    recorder=RetainedCampaignRecorder(page,root=output/'recording',duration=1800)
    recording={'state':'not_started'};started=False
    try:
        try:await recorder.start();started=True
        except Exception as exc:recording=dict(state='recording_failed',error_type=type(exc).__name__)
        result=await perform_on_page(worker,packet,operation,options,seq,page)
    finally:
        if started:
            try:recording=await recorder.stop()
            except Exception as exc:recording=dict(state='recording_failed',error_type=type(exc).__name__)
        try:write_evidence(output/'recording-result.json',recording)
        except OSError as exc:recording=dict(recording,receipt_error_type=type(exc).__name__)
    if 'original_result' in result:
        original=dict(result['original_result'],recording=recording)
        if packet['operation']=='discount':original['evidence_path']=str(output/'returned-result.json')
        write_evidence(output/'returned-result.json',original)
        return finish_transfer(worker,packet,original)
    return dict(result,recording=recording)


async def perform_on_page(worker,packet,operation,options,seq,page):
    from .campaign_bound_transfers import ARTIFACT_ROOT, verified_erp_claim, write_evidence
    jid=packet['job_id'];source=worker.output/jid
    folder=source/'takeover';output=folder/str(seq);output.mkdir(parents=True,exist_ok=True)
    if operation=='inspect':return await inspect_page(page,packet,output)
    await guard(page,packet,inspect=operation=='reload')
    state=worker.jobs.db.execute('SELECT state FROM campaign_ui_takeovers WHERE job_id=?',(jid,)).fetchone()[0]
    if operation=='reload':
        if state!='active' or packet['operation'] not in ('discount_readback','product_export'):
            raise SurfaceError('takeover_reload_not_safe_for_current_step')
        if await page.locator('.tbd-drawer-body:visible,.next-dialog:visible,[role="dialog"]:visible').count():
            raise SurfaceError('takeover_reload_would_discard_open_form')
        await page.reload(wait_until='domcontentloaded',timeout=10000)
        await guard(page,packet)
        return dict(state='reloaded_once',platform_write=False)
    if operation=='click':
        node=await one_visible(page.get_by_text(options['label'],exact=True))
        await node.click(timeout=3000)
        return dict(state='ui_adjusted',platform_write=False)
    identity=packet['identity'];claim=packet['claim']
    driver=CampaignPageIO(page,identity,roots=[ARTIFACT_ROOT,worker.output],output=output)
    if operation=='baseline':
        if packet['operation']!='signup' or state!='active':raise SurfaceError('takeover_baseline_only_before_signup')
        value=await driver.upload_baseline();write_evidence(folder/'before.json',value)
        return dict(state='baseline_saved')
    if operation=='upload':
        current=await verified_erp_claim(claim['claim_id'])
        if current!=claim:raise SurfaceError('takeover_approved_claim_changed')
        if packet['operation']=='discount':
            _,req=original_transfer(worker.jobs.db,jid)
            # Reuse the fixed, guarded form adapter on the page the AI repaired;
            # never open a fresh page and discard those UI adjustments.
            terminal=await worker._transfer('discount',req,page,output)
            if not discount_terminal_complete(terminal):
                raise SurfaceError('takeover_discount_terminal_not_ready')
            return {'original_result':dict(terminal,takeover_same_job=True)}
        if packet['operation']!='signup':raise SurfaceError('takeover_upload_operation_not_supported')
        from .campaign_submission_checklist import validate_claim_submission_checklist
        validate_claim_submission_checklist(current,identity)
        if not (folder/'before.json').is_file():raise SurfaceError('takeover_signup_baseline_missing')
        data=workbook_payload(claim['file']['path'],claim['file']['sha256'])
        trigger=await one_visible(page.get_by_text('导入表格',exact=True))
        consumed=await verified_erp_claim(claim['claim_id'],consume_job=jid)
        if consumed.get('dispatch_consumed') is not True or consumed.get('job_id')!=jid:
            raise SurfaceError('takeover_original_claim_not_consumed')
        await driver.guard()
        async with page.expect_file_chooser(timeout=6000) as chosen:await trigger.click(timeout=3000)
        await (await chosen.value).set_files(data,timeout=8000)
        return dict(state='write_unknown',platform_write_possible=True,automatic_retry=False)
    if operation=='collect':
        if packet['operation'] not in ('signup','discount'):return await collect_read(worker,packet,page,output)
        if state!='write_unknown':raise SurfaceError('takeover_no_original_upload_to_collect')
        await verified_erp_claim(claim['claim_id'],existing_job=jid)
        if packet['operation']=='discount':
            terminals=list(source.glob('discount-result.json'))+list(folder.glob('*/discount-result.json'))
            if not terminals:terminals=list(source.glob('discount-official-terminal.json'))+list(folder.glob('*/discount-official-terminal.json'))
            if len(terminals)!=1:raise SurfaceError('takeover_original_discount_terminal_missing')
            from .campaign_discount_create import DiscountCreate
            terminal=read(terminals[0])
            from .campaign_discount_name_guard import recorded_name
            if terminal.get('claim') and terminal['claim']!=claim:raise SurfaceError('takeover_original_discount_claim_changed')
            if terminal.get('state') in ('verified_offer_terminal','verified_partial_offer_terminal'):
                # Preserve the originally observed complete readback. ERP still
                # validates its exact SKU/window values and physical feedback.
                if terminal.get('feedback'):
                    terminal['feedback']=copy_feedback(terminal['feedback'],terminals[0].parent,output)
                return {'original_result':dict(terminal,takeover_same_job=True)}
            if not terminal.get('submitted_name'):raise SurfaceError('takeover_original_discount_name_missing')
            name=recorded_name(terminal,claim['claim_id'])
            if terminal.get('feedback'):terminal['feedback']=copy_feedback(terminal['feedback'],terminals[0].parent,output)
            discount=DiscountCreate(page,shop=identity['shop_name'],start=claim['start'],end=claim['end'],roots=[ARTIFACT_ROOT,worker.output],output=output)
            result=await discount.finish_readback(terminal,name=name,sku_rows=claim['sku_rows'],already_home=urlsplit(page.url).path.endswith('/mkt-tools-reduce/home'))
            if not discount_terminal_complete(result):raise SurfaceError('takeover_discount_terminal_not_ready')
            return {'original_result':dict(result,claim=claim,takeover_same_job=True)}
        baseline=folder/'before.json'
        if not baseline.exists():baseline=source/'before.json'
        if not baseline.exists():raise SurfaceError('takeover_original_upload_baseline_missing')
        driver.upload_attempted=True
        terminal=await driver.await_upload_terminal(before=read(baseline),filename=Path(claim['file']['path']).name,
            expected_count=len(claim['items']),timeout=60)
        if terminal.get('state') not in ('terminal','terminal_processing_failed'):raise SurfaceError('takeover_official_terminal_not_ready')
        evidence=output/'official-batch.json';write_evidence(evidence,terminal)
        if terminal.get('counts',{}).get('failed'):
            try:terminal['feedback']=await driver.download_feedback_once(terminal['batch'])
            except Exception as exc:terminal['report_gate']=dict(reason='official_feedback_download_failed',error_type=type(exc).__name__,batch=terminal['batch'],automatic_retry=False)
        return {'original_result':dict(terminal,claim=claim,evidence_path=str(evidence),per_item_acceptance_verified=False,takeover_same_job=True)}
    raise SurfaceError('takeover_operation_not_allowed')


def copy_feedback(file,source,output):
    path=Path(file['path']).resolve(strict=True)
    raw=path.read_bytes()
    if not path.is_relative_to(source.resolve()) or hashlib.sha256(raw).hexdigest()!=file['sha256']:
        raise SurfaceError('takeover_original_feedback_changed')
    target=output/path.name
    with target.open('xb') as stream:stream.write(raw)
    return dict(file,path=str(target))


def discount_terminal_complete(result):
    return (result.get('state') in ('verified_offer_terminal','verified_partial_offer_terminal')
        or (result.get('state')=='official_import_terminal' and result.get('success')==0
            and type(result.get('failed')) is int and result['failed']>0 and bool(result.get('feedback'))))
